"""Chapter 6: Methodology and Software Implementation for FlowSense.

methodology_blocks() is also rendered (renumbered) by document 9, application_blocks() by document 12; blocks() is the report chapter.
Numbers come from facts.py (experiments/**/metrics.json); formulas are exactly what smart_traffic/sim.py, predictor.py and vision.py compute.
"""

from . import facts as F
from .blocks import B, CODE, EQ, FIG, H1, H2, H3, N, P, TAB
from .refs import CITE as R


def c(*keys):
    return ", ".join(f"[{R[k]}]" for k in keys)


def methodology_blocks():
    pr = F.PR
    n_samples = pr["n_samples"]
    shipped = pr["shipped_fit"]["metrics"]
    b = []

    # ---------------------------------------------------------------- 6.1
    b += [H2("6.1 Overall methodology"),
          P("FlowSense treats traffic management as one measurable pipeline. Vehicles are counted and classified from a camera frame, queues are forecast a short time ahead, signal timing is computed from "
            "the measured and forecast demand, an ambulance is given a green corridor, neighbouring junctions share what they can see coming, and violations are logged. "
            f"The base paper {c('base')} supplies one stage of this chain, emergency pre-emption triggered by a light-bar detector, on top of an optimised controller; FlowSense keeps that idea and builds the other stages around it. "
            "Because a real junction cannot be used for experiments, every stage that touches signals is evaluated in a seeded traffic-network simulator that runs four controllers on identical traffic. The method has seven steps:"),
          N("**Generate demand.** Vehicles arrive at the entry roads of a 2 x 2 or 3 x 3 grid of junctions as Poisson arrivals, scaled by a demand slider and a morning and evening rush-hour profile. A fixed seed makes the demand identical for all controllers.",
            "**Sense.** At every second each approach knows its queue (vehicles and passenger-car units), the vehicles that will arrive from upstream within 8 s, and whether an ambulance is queued or is within 15 s.",
            "**Forecast.** Every 10 s a gradient-boosted model predicts each approach's queue 30 s ahead from eleven features.",
            "**Decide.** Each junction compares the pressure of its green phase with that of the red phase, and switches under minimum and maximum green rules; an ambulance overrides the comparison.",
            "**Discharge and move.** Queued vehicles leave at the saturation flow while their phase is green, travel the 12 s link to the next junction or leave the network; a full downstream queue blocks the release (spill-back).",
            "**Observe.** The simulator records waiting time, queues, throughput, ambulance delay, violations, idling fuel and CO2; the vision layer in parallel detects vehicles in an image, flags light bars and recommends a green time.",
            "**Compare.** Five seeds per setting, two grid sizes, a demand sweep, an ambulance-heavy test and an ablation are run by `scripts/run_experiments.py`, and the vision layer is scored on synthetic scenes and on two public sets of real photographs."),
          FIG(F.diag("02_high_level_workflow.png"), "Methodology as a pipeline: demand, sensing, forecasting, decision, discharge and observation.", 5.4)]

    # ---------------------------------------------------------------- 6.2
    b += [H2("6.2 Data"),
          P(f"FlowSense has three kinds of data, and keeping them apart matters for reading the results. **Simulated traffic** is the only input to the controllers: it is generated, not collected, and its parameters (arrival rates, "
            "saturation flow, link time, vehicle mix) are the project's own assumptions. **Training data for the forecaster** is generated by the same simulator under the adaptive controller. "
            "**Real photographs** are used only to *evaluate* the vision layer; nothing is trained on them."),
          TAB("Datasets and their roles.",
              ["Data", "Source", "Size", "Role"],
              [["Simulated demand", "`Sim` with seeds 40-44 (benchmarks)", "5 seeds x 1,800 s per setting", "Controller comparison"],
               ["Forecaster training set", "Six simulated runs, adaptive controller, snapshots every 10 s", f"{n_samples:,} rows x {pr['n_features']} features", "Train and test the queue forecaster"],
               ["Synthetic overhead scenes", "`render_scene`, seeds 1000-1299", "300 scenes, 2,754 vehicles", "Detector check (in-domain)"],
               ["Real mixed-traffic frames", f"Visaitech v0.1 (CC BY 4.0) {c('ds_traffic')}", "293 frames, 1,506 boxes (1,467 vehicles)", "Evaluate YOLOv8n"],
               ["Real ambulance photographs", f"shravya11 (CC BY 4.0) {c('ds_ambulance')}", "300 ambulance + 300 other photos (of 4,749)", "Evaluate the light-bar rule"],
               ["Bundled sample photograph", "Ultralytics `bus.jpg`", "1 image, 1080 x 810", "Vision-page demonstration"]],
              widths=[1.4, 2.3, 1.6, 1.3], align=["l", "l", "l", "l"], size=9.5),
          P("The simulator's demand model is a Poisson process per entry road with base rates of 0.15 vehicles per second on the north and south entries and 0.10 on the east and west entries, multiplied by the demand slider "
            "and by a time-of-day profile that peaks at 08:30 and 17:30 (the equation below). Vehicles are 68 % cars, 13 % bikes, 6 % buses and 13 % trucks; 5 % of cars are red-light runners that cross after waiting 25 s on a red, and a wrong-way driver is "
            "generated with probability 0.0003 per entry road per second. Each vehicle has a route drawn once: straight with probability 0.78, a turn to one side with 0.11 and the other with 0.11; ambulances always go straight. "
            "Fuel and CO2 are derived from queue length (the fuel equation in Section 6.5.4), not simulated per vehicle."),
          EQ("λ_a(t) = r_a · d · m(h),   m(h) = 0.7 + 0.5·exp(−((h − 8.5)/0.9)²) + 0.55·exp(−((h − 17.5)/1.1)²),   N_a(t) ~ Poisson(λ_a(t))"),
          P("Three limits of this data are stated here because later chapters depend on them. The demand and discharge parameters are not calibrated to a real junction. The real photographs come from a dashcam in South Asian mixed traffic "
            "(2-wheelers, auto-rickshaws) and from general ambulance photographs, not from fixed junction cameras. And the two real sets were used with the application's own default settings, with no tuning on them.")]

    # ---------------------------------------------------------------- 6.3
    b += [H2("6.3 Feature construction"),
          P("There is no image preprocessing for the controllers; the simulator hands them counts. Feature construction matters only for the forecaster. For each approach `Sim.feature_matrix()` returns one row of eleven numbers, "
            "computed from the queue history, the arrivals and the signal state. The target is the approach's queue length 30 s later. No scaling is applied because the model is tree-based."),
          TAB("Forecaster features.",
              ["Feature", "Definition", "GB importance"],
              [[f"`{k}`", d, f"{pr['shipped_fit']['importance'][k]:.3f}"] for k, d in [
                  ("queue", "Vehicles waiting now"), ("pcu_queue", "The same queue weighted by passenger-car units"),
                  ("queue_lag10", "Queue 10 s ago"), ("queue_lag30", "Queue 30 s ago"), ("inflow_30s", "Vehicles that arrived in the last 30 s"),
                  ("inbound_15s", "Vehicles in transit due within 15 s"), ("is_green", "1 if this approach's phase is green and not clearing"),
                  ("green_time", "Seconds since the junction's phase began"), ("is_entry", "1 if the approach is fed from outside the grid"),
                  ("sin_day", "sin(2π·hour/24)"), ("cos_day", "cos(2π·hour/24)")]],
              widths=[1.3, 4.0, 1.0], align=["l", "l", "c"], size=10),
          P("The current queue carries 69.2 % of the importance, the queue 30 s ago 13.3 % and the PCU queue 8.8 %: the forecaster is mostly a refined \"the queue stays about what it is\" model, which is why it improves on persistence by 35 % "
            "and not by more. The 30-second inflow and the inbound count carry almost no importance, so the forecaster uses little information about arriving platoons; the controller adds that information separately through its inbound term.")]

    # ---------------------------------------------------------------- 6.4
    b += [H2("6.4 Algorithm choice and justification"),
          H3("6.4.1 Pressure-based signal control"),
          P(f"Fixed-time plans of the Webster kind {c('webster')} are what most junctions run; they are the baseline. A queue-actuated rule that compares the demand of the two phases is simple, needs only counts, and is the family that "
            f"max-pressure control {c('varaiya')} belongs to. Reinforcement-learning controllers {c('intellilight')} can do better but need long training in a simulator and are hard to inspect, so the project preferred a rule whose every term can be explained and ablated. "
            "The advanced controller keeps the adaptive rule's switching test and changes only what it calls demand: the PCU-weighted queue plus a forecast term, an arriving-platoon term, a fairness term and a spill-back damping factor."),
          H3("6.4.2 Passenger-car units"),
          P(f"A bus occupies more road and discharges more slowly than a bike, so counting vehicles misjudges demand. Passenger-car-equivalent weights are standard practice {c('hcm')}; FlowSense uses car 1, bike 0.5, truck 2, bus 3 and ambulance 1, "
            "and uses the same weights in the simulator's pressure and in the vision layer's density estimate so that a camera count could feed the controller directly."),
          H3("6.4.3 Forecast term, inter-junction look-ahead and the green wave"),
          P("A queue forecast lets the controller give green to an approach before its queue has grown; the term is `0.7 · max(forecast − queue, 0)`, so a forecast below the present queue never reduces demand and a poor forecast can only add a bounded bias. "
            "Look-ahead is the project's reading of \"inter-junction communication\": a junction reads the transit list of vehicles already released by its neighbours and adds their PCU to the pressure of the approach they will join. "
            "A green wave follows from extending the emergency look-ahead from 5 s (one junction, base-paper style) to 15 s, so that junctions along the ambulance's route switch before it arrives. "
            "Spill-back damping multiplies pressure by 0.3 when the receiving queue is within 4 vehicles of capacity, so that green is not wasted on vehicles that cannot move."),
          H3("6.4.4 Gradient boosting for the forecaster"),
          P(f"Three models were compared: persistence, Random Forest {c('rf')} and gradient boosting {c('gbm')}. On the application's own split the two ensembles are equivalent (MAE {shipped['Random Forest']['mae']:.3f} for Random Forest and {shipped['Gradient Boosting (used)']['mae']:.3f} for gradient boosting; persistence {shipped['Persistence baseline']['mae']:.3f}). "
            "Gradient boosting was kept because it was already the shipped model and is the smaller of the two, not because it won; a ridge regression was also tried and is only slightly better than persistence on random splits. Chapter 8 reports how all of them behave on a simulation they have not seen."),
          H3("6.4.5 Pretrained YOLOv8n and an HSV light-bar rule"),
          P(f"YOLO {c('yolo')} detectors give counts and classes in one pass; the nano variant of YOLOv8 {c('ultralytics')} runs in tens of milliseconds on a CPU, and its COCO weights already cover car, motorcycle, bus and truck {c('coco')}. "
            f"The base paper trained a YOLO26m light-bar detector on 3,130 annotated images; the batch had no such dataset or GPU, so FlowSense uses a hand-written rule instead: red and blue pixels in fixed HSV ranges, dilated, whose intersection marks a light bar. "
            "The rule is transparent and needs no data, and its weakness is exactly that it is hand-tuned; Chapter 8 measures how far it falls from a trained detector."),
          H3("6.4.6 Why a simulator, and why not SUMO"),
          P(f"SUMO {c('sumo')} is the accepted tool and the one the base paper used, but it needs installation, a network and a route file for every experiment and a TraCI client for control. A 415-line Python simulator runs 1,800 s in a fraction of a second, makes "
            "the identical-demand guarantee trivial, and can be shipped inside the web application. The price is that the simulator's absolute numbers are the project's, and Chapter 8 compares percentages with the base paper, never seconds.")]

    # ---------------------------------------------------------------- 6.5
    b += [H2("6.5 Mathematical formulation"),
          P("Every formula below is what the code computes. Symbols: j a junction, a an approach (N, E, S, W), φ a phase (0 north-south, 1 east-west), Q the queue (a list of vehicles), π the PCU weight, CAP = 30 the approach capacity, t the simulated second."),
          H3("6.5.1 Queue weight and the advanced pressure"),
          EQ("W_{j,a} = Σ_{v ∈ Q_{j,a}} π(type(v)),   π(car) = 1, π(bike) = 0.5, π(bus) = 3, π(truck) = 2, π(ambulance) = 1"),
          EQ("P_{j,a} = ( W_{j,a} + 0.7·max(f̂_{j,a} − |Q_{j,a}|, 0) + I_{j,a} + w_head/12 ) · γ_{j,a},   γ = 0.3 if |Q_down(j,a)| ≥ CAP − 4 else 1"),
          P("Here f̂ is the forecast queue, I the PCU of vehicles inbound within 8 s, w_head the waiting time in seconds of the vehicle at the head of the queue (0 if empty), and Q_down the queue of the receiving approach straight ahead. "
            "The adaptive and emergency-aware controllers use P = W only. The phase pressure is the sum over its two approaches:"),
          EQ("Π_{j,φ} = Σ_{a ∈ φ} P_{j,a}"),
          H3("6.5.2 Switching rule"),
          P("With g_min = 15, g_max = 60 for the adaptive and emergency-aware controllers and g_min = 13, g_max = 60 for the advanced one, a junction in phase φ with green age τ switches to the other phase φ' (after a 3 s clearance) when"),
          EQ("τ ≥ g_min  and  ( Π_{j,φ} ≤ 0.01 and Π_{j,φ'} > 0,   or   Π_{j,φ'} > 2·Π_{j,φ} + 4,   or   τ ≥ g_max and Π_{j,φ'} > 0 )"),
          P("The fixed-time controller instead switches when τ ≥ 30. After a phase begins, vehicles are released only after a 2 s start-up loss, at saturation flow s = 0.5 vehicles per second per approach: a credit accumulates by s every green second and one vehicle leaves per whole credit."),
          EQ("credit ← credit + s each green second after τ > 2;   release the head vehicle while credit ≥ 1 and the next queue has fewer than CAP vehicles"),
          H3("6.5.3 Emergency target"),
          P("For a junction, let d_a be 0 if an ambulance is in the queue of approach a, otherwise the number of seconds until an inbound ambulance arrives (only if within the look-ahead L, 5 s for the emergency-aware controller and 15 s for the advanced one). Then"),
          EQ("a* = argmin_a d_a,   φ* = phase(a*);   if φ* ≠ φ and τ ≥ 2 then switch to φ* now, else hold φ"),
          P("Inside the discharge step an ambulance is moved to the head of its queue (\"sirens clear the lane\"). The count of pre-emptions increments once per continuous override."),
          H3("6.5.4 Forecast, density and resources"),
          EQ("ŷ_{j,a} = clip( GB(x_{j,a}(t)), 0, 40 ),   y_{j,a} = |Q_{j,a}(t + 30)|,   MAE = (1/n) Σ |y − ŷ|,   R² = 1 − Σ(y − ŷ)² / Σ(y − ȳ)²"),
          EQ("GB: F_m(x) = F_{m−1}(x) + ν·h_m(x),   ν = 0.08,   m = 1 … 160,   h_m a regression tree of depth ≤ 4 fitted to the residuals on a 0.9 subsample"),
          EQ("ρ = Σ_c π(c)·n_c / 14,   level = LOW (ρ < 0.35), MEDIUM (< 0.7), HIGH (< 1.0), JAMMED;   g = 12 if an ambulance is present else min(60, max(15, 12 + 3.2·Σ_c π(c)·n_c))"),
          EQ("Fuel (L) = ( Σ_t q_total(t) ) · 0.6 / 3600,   CO2 (kg) = 2.31 · Fuel,   D̄ = mean over completed vehicles of w_v,   Δ_vs = 100 · (1 − D̄_advanced / D̄_controller)"),
          P("The fuel figure assumes 0.6 L per hour for an idling vehicle; both constants are assumptions of the simulator and make fuel and CO2 proportional to total queued vehicle-seconds. "
            "The light-bar score used by the vision rule is s = min(1, 2·min(r, b)/(r + b) · min(1, (r + b)/120)), where r and b are the numbers of red and blue pixels in the cluster; a cluster must have at least 12 pixels of each colour, and a vehicle box is relabelled `ambulance` when s > 0.25 for YOLO boxes (> 0.2 for the classical detector)."),
          H3("6.5.5 A worked example"),
          P("Take junction J in the north-south phase with green age τ = 20 s. The north approach holds four cars and one bus (W = 4 + 3 = 7), the forecaster predicts 10 vehicles against a queue of 5 (0.7 · 5 = 3.5), vehicles worth 2 PCU are inbound, "
            "the head vehicle has waited 24 s (24/12 = 2) and the receiving queue is not full, so P_N = 7 + 3.5 + 2 + 2 = 14.5. The south approach holds two cars and a truck (W = 4), its forecast equals its queue, nothing is inbound and the head has waited 12 s (1), so P_S = 5. "
            "The phase pressure is Π_NS = 19.5. If the east-west phase has Π_EW = 47, then 47 > 2 · 19.5 + 4 = 43 and, because τ ≥ 13, the junction starts its 3-second clearance and switches. With Π_EW = 40 it would keep the green; "
            "plain adaptive control, without the forecast, inbound and fairness terms, would have seen Π_NS = 11 and switched at any Π_EW above 26."),
          H3("6.5.6 The pressure code"),
          P("The pressure of a phase is a few lines in `smart_traffic/sim.py`; it is reproduced because the whole of the \"advanced\" idea is in it."),
          CODE('''def _pressure(self, j, phase, adv):
    total = 0.0
    for a, name in enumerate(APPROACHES):
        if PHASE_OF[name] != phase:
            continue
        qq = self.q[j][a]
        w = self.wq(j, a)
        if adv:
            w += 0.7 * max(float(self.pred[j, a]) - len(qq), 0.0)     # ML forecast
            w += float(self._inbound[j, a])                           # arriving platoon
            if qq:
                w += qq[0].wait / 12.0                                # fairness
            nh = self._next_hop_of_straight(j, a)
            if nh is not None and len(self.q[nh[0]][nh[1]]) >= CAP - 4:
                w *= 0.3                                              # downstream full
        total += w
    return total''', 8)]

    # ---------------------------------------------------------------- 6.6
    gb = pr["shipped_fit"]
    b += [H2("6.6 Models and configuration"),
          H3("6.6.1 Queue forecaster"),
          TAB("Forecaster configuration.",
              ["Item", "Value"],
              [["Model", "scikit-learn 1.5.0 `GradientBoostingRegressor`: 160 trees, max depth 4, learning rate 0.08, subsample 0.9, random_state 0"],
               ["Baselines", "`RandomForestRegressor` (80 trees, depth 10, random_state 0); persistence (the current queue); ridge regression in the extra study"],
               ["Training data", f"{n_samples:,} rows from six simulated 1,800 s runs (2 x 2 and 3 x 3 alternating, demand 0.7 / 1.0 / 1.3 / 1.6, start hours 7, 8, 12, 17), snapshots every 10 s from t = 40 s, target the queue 30 s later"],
               ["Split", "Random 75 % / 25 % with random_state 1 (the application); five further random splits and a leave-one-simulation-out study in `run_experiments.py`"],
               ["Fit time", f"{gb['fit_seconds']:.1f} s on the CPU; inference for 16 rows {F.TH['predictor_batch16_ms']:.2f} ms"],
               ["Use", "Called every 10 simulated seconds by the advanced controller; output clipped to 0-40"]],
              widths=[1.3, 5.0], align=["l", "l"], size=10),
          P(f"As the application trains it, the model scores MAE {shipped['Gradient Boosting (used)']['mae']:.3f} vehicles and R² {shipped['Gradient Boosting (used)']['r2']:.3f} on the held-out quarter against {shipped['Persistence baseline']['mae']:.3f} and {shipped['Persistence baseline']['r2']:.3f} for persistence. "
            "Because the quarter is drawn at random from snapshots that are ten seconds apart, rows from the same run appear on both sides of the split; Chapter 8 repeats the evaluation with whole runs held out and reports that the result is much weaker."),
          H3("6.6.2 Vision layer"),
          TAB("Vision configuration.",
              ["Item", "Value"],
              [["Vehicle detector", "Ultralytics 8.4.186 `yolov8n.pt` (COCO, not fine-tuned); classes car, motorcycle (bike), bus, truck; confidence threshold 0.3 (adjustable)"],
               ["Light-bar rule", "HSV: red H 0-8 or 172-180, blue H 100-130, S ≥ 120, V ≥ 190; 3 x 3 elliptical opening; dilation of 5 % of the shorter image side; connected components of the red-and-blue intersection; ≥ 12 pixels of each colour"],
               ["Ambulance flag", "A YOLO box whose upper region (from 0.3 box heights above its top to 0.6 below) contains a cluster with score > 0.25"],
               ["Classical detector", "For synthetic overhead scenes: background and lane-paint removal, morphological clean-up, contour size classes (bike < 900 px area, car < 95 px long side, truck < 130 px, else bus)"],
               ["Density report", "PCU / 14 capacity; four levels; recommended green 12 s with an ambulance, else 12 + 3.2 PCU clamped to 15-60 s"],
               ["Training", "None: the project trains no vision model"]],
              widths=[1.3, 5.0], align=["l", "l"], size=10),
          H3("6.6.3 Experiment protocol"),
          P("`scripts/run_experiments.py` fixes the protocol so that the numbers can be reproduced: controllers are compared on seeds 40 to 44 for 1,800 simulated seconds at demand x1.2 starting at 08:00, on both grids; the demand sweep uses five levels from x0.6 to x1.8 with three seeds and 1,200 s; "
            "the ambulance-heavy test generates one ambulance per 60 s on average for 3,600 s; the ablation removes one mechanism at a time; the forecaster study repeats the application's split five times and holds out each of the six training runs in turn. "
            "Results are given as mean and sample standard deviation over seeds. The first three seeds are the ones used by the Benchmark screen, so the screen reproduces a subset of the tables.")]
    return b


def application_blocks():
    a, w = F.API_PORT, F.WEB_PORT
    b = []
    # ---------------------------------------------------------------- 6.7
    b += [H2("6.7 Application architecture"),
          P(f"FlowSense runs as two processes. The API is a FastAPI application served by Uvicorn on 127.0.0.1:{a}; the console is a React 19 single-page application built with Vite 8 and Tailwind 4 and served by the Vite development server on port {w}, which proxies `/api` to the API. "
            "The API's three layers are the route layer (`backend/main.py`, 210 lines: input models, error handlers, the authentication dependency), the service layer (`backend/service.py`, 437 lines: the live simulation, the landing preview, the predictor wrapper, benchmark, vision and violation payloads) "
            "and the engine (`smart_traffic/`). The service layer holds one `threading.RLock`; every route that touches the shared live simulation takes it, while benchmark and sweep routes build their own simulators and do not."),
          FIG(F.diag("01_system_architecture.png"), "Layered architecture of FlowSense.", 5.2),
          P("**Start-up.** `S.start_background()` launches a daemon thread that trains the forecaster (about 6 s) and then runs one 900 s fixed-time and one advanced simulation to compute the headline numbers shown on the landing page. "
            "Until training ends, routes that need the forecaster answer 503 with a hint to retry, and `/api/health` reports `predictor_ready`. **Import order.** `backend/main.py` imports PyTorch first because, on Windows, PyTorch's DLLs fail to initialise (error 1114) if NumPy, pandas or OpenCV are already loaded."),
          P("**Live simulation.** `Live` owns one `Sim` (2 x 2, advanced, demand 1.0, seed 7). Configuration changes (grid, controller, demand, emergencies, ML toggle) take effect immediately; changing the grid restarts the simulation. "
            "`step(seconds)` runs the engine and `snapshot()` returns the clock, KPIs, a banner (\"signals pre-empting\" or \"this controller ignores it\"), the map geometry (roads, signal states, one square per vehicle) and the junction table. "
            "The console's \"Run live\" button simply repeats two-second steps and redraws."),
          P("**Benchmark.** The benchmark route runs each of the four controllers over the requested seeds (seed = 40 + i), averages the summaries, computes the percentage changes shown as KPI tiles, caches the result by its settings and stores the violation counts for the Violations screen. "
            f"The first request with four controllers, three seeds and 1,800 s takes about {F.API['results'][-3]['mean_ms'] / 1000:.1f} s; a repeat is served from the cache in about {F.API['results'][-2]['mean_ms']:.0f} ms."),
          P("**Console.** The React application lazy-loads its eight pages and wraps the signed-in area in a `LiveProvider`, which holds the latest live snapshot, a busy flag and a version counter. Moving between screens therefore does not restart the simulation; "
            "a change made by another screen (the Prediction screen can advance the live simulation by 180 s) bumps the version so that the Live screen refreshes. `api.js` adds the token to every request, logs each call and its duration to an on-screen activity panel, "
            "and signs the user out on a 401. The road map is drawn as SVG from the geometry in the snapshot, and charts use Recharts."),
          TAB("Modules and their responsibilities.",
              ["Module", "Responsibility"],
              [["smart_traffic/sim.py", "Vehicle and Sim classes; demand; four controllers; upstream scan; discharge with spill-back and violations; feature matrix; summary; benchmark helper"],
               ["smart_traffic/predictor.py", "Dataset builder and QueuePredictor (fit, predict, metrics, importance)"],
               ["smart_traffic/vision.py", "YOLO loader and detector; light-bar masks and clusters; classical detector; density report; annotate; synthetic scene renderer"],
               ["backend/main.py", "Routes, pydantic request models, JSON error handlers, bearer-token dependency, startup hook"],
               ["backend/service.py", "Live, Preview, Predictor; benchmark and sweep; vision payloads (base64 JPEG); prediction and violation payloads; `ApiError`"],
               ["backend/auth.py, config.py", "HS256 token creation and verification; credential check; `.env` loader with safe defaults"],
               ["frontend/src", "App routes (lazy-loaded pages), `api.js` (axios with token and error description), live-simulation provider, theme and activity log, UI components, SVG traffic map"]],
              widths=[1.9, 4.5], align=["l", "l"], size=9.5)]

    # ---------------------------------------------------------------- 6.8
    b += [H2("6.8 API design"),
          P("All routes are under `/api`. Four are public; the others need an `Authorization: Bearer <token>` header. Errors have the form `{\"detail\": {\"message\": ..., \"hint\": ...}}` for every status code, including framework validation errors, "
            "which are rewritten by a handler so that the console never shows a raw stack trace."),
          TAB("The twenty endpoints.",
              ["Method and path", "Auth", "Request", "Response"],
              [["GET /api/health", "no", "-", "ok, predictor_ready, predictor_error, yolo_available, live_clock"],
               ["POST /api/auth/login", "no", "{email, password}", "token, user"],
               ["GET /api/auth/demo", "no", "-", "demo email and password for the sign-in page"],
               ["GET /api/public/pulse", "no", "-", "preview map, KPIs, up to 12 event lines, headline numbers"],
               ["GET /api/auth/me", "yes", "-", "name, email"],
               ["GET /api/meta", "yes", "-", "controllers, approaches, grids, vehicle types, version"],
               ["GET /api/live", "yes", "-", "live snapshot"],
               ["PUT /api/live/config", "yes", "{grid, controller, demand 0.4-2.0, emergencies, use_ml}", "live snapshot"],
               ["POST /api/live/step", "yes", "{seconds 1-900}", "live snapshot"],
               ["POST /api/live/ambulance", "yes", "-", "snapshot + entry {junction, approach}"],
               ["POST /api/live/reset", "yes", "-", "snapshot at t = 0"],
               ["POST /api/benchmark", "yes", "{grid, seconds 300-3600, demand 0.5-1.8, seeds 1-5, start_hour 0-23, use_ml}", "settings, KPIs, per-controller results, table"],
               ["POST /api/benchmark/sweep", "yes", "{grid, use_ml}", "levels 0.6-1.8, delay series per controller"],
               ["GET /api/vision/synthetic", "yes", "?vehicles 2-16, ambulance, flash A/B, seed", "frame, annotated frame, detections, density report"],
               ["GET /api/vision/sample", "yes", "?conf", "same, YOLOv8n on the bundled photo"],
               ["POST /api/vision/analyze", "yes", "multipart file (≤ 12 MB), conf", "same, YOLOv8n on the upload"],
               ["GET /api/prediction", "yes", "-", "KPIs, metrics, scatter (≤ 1,500 points), importance"],
               ["GET /api/prediction/live", "yes", "-", "per-approach queue now and forecast, worst approach"],
               ["POST /api/prediction/simulate", "yes", "-", "advances the live simulation 180 s; snapshot"],
               ["GET /api/violations", "yes", "-", "KPIs, by junction, per minute, log (≤ 300), last benchmark"]],
              widths=[1.9, 0.5, 2.1, 2.0], align=["l", "c", "l", "l"], size=9),
          P("Two design points are worth noting. The vision routes return both the original and the annotated image as base64 JPEG data URLs so that the console needs no second request. "
            "The benchmark route is a plain function of its settings, so it can be cached by key and the console can show a result instantly when the settings are unchanged.")]

    # ---------------------------------------------------------------- 6.9
    b += [H2("6.9 Security and error handling"),
          P("FlowSense is a demonstration console, not a hardened service, and its security is proportionate to that. Authentication is one configured operator account (`DEMO_EMAIL`, `DEMO_PASSWORD` in `.env`, defaulting to the account shown on the sign-in page). "
            "A successful login returns an HS256 token built from the standard library: a base64url header and payload (subject, name, expiry 12 hours ahead) and an HMAC-SHA256 signature. The signature and the credentials are compared with `hmac.compare_digest`; "
            "a tampered or expired token is rejected with 401, and the console then clears its stored token and returns to the sign-in page."),
          B("**Signing key.** `JWT_SECRET` from `.env` is used only if it has at least 32 characters and is not the `generate-...` placeholder; otherwise a fixed development key in the source is used, which is acceptable for a local demo and unsafe anywhere else.",
            "**Input validation.** Request bodies are pydantic models with bounds (demand 0.4-2.0, step 1-900 s, e-mail and password length); benchmark settings are range-checked and answer 422 with the allowed ranges; an unknown grid or controller answers 422 naming the valid values.",
            "**Uploads.** The image route reads at most 12 MB + 1 byte and answers 413 beyond 12 MB; a file that OpenCV cannot decode answers 415 asking for a JPG or PNG frame.",
            "**Missing or failing components.** Without `ultralytics` the YOLO routes answer 503 with the install command; if YOLO raises (for example the first run cannot download `yolov8n.pt` offline) the answer is 502 with the exception text; while the forecaster trains, forecast-dependent routes answer 503; if training failed they answer 500 with the reason.",
            "**Error shape.** One handler each for the service's `ApiError`, for `HTTPException` and for request validation produce the same `{message, hint}` JSON; the console's `describeError` shows both fields.",
            "**Not done.** There is no rate limiting, no HTTPS, no per-user data, no CSRF protection beyond bearer tokens, and no audit trail; the live simulation is one shared object for every signed-in browser."),
          P("The 14 API tests and the 33 smoke checks (Chapter 7) exercise the 401, 422, 413/415 and 503 paths.")]

    # ---------------------------------------------------------------- 6.10
    b += [H2("6.10 Installation and execution"),
          P("`run.bat` starts the whole application on Windows: it creates `.venv` if needed (and rebuilds it if it points at a missing Python), installs `backend/requirements.txt` (FastAPI, Uvicorn, NumPy, pandas, scikit-learn, OpenCV, python-multipart) "
            "and then `backend/requirements-yolo.txt` (Ultralytics and PyTorch, a large download; if it fails the application still runs and only the YOLO modes of the Vision page are unavailable), runs `npm install` in `frontend/` on first use, "
            f"starts the API on port {a} and the Vite server on port {w} in two minimised windows, and opens the browser. `run.bat nobrowser` skips the browser."),
          TAB("Requirements and settings.",
              ["Item", "Value"],
              [["Python / Node", "Python 3.10 or newer (3.11.9 used here); Node 20 or newer (24.19 used here)"],
               ["Key packages (as run)", "FastAPI 0.143.3, scikit-learn 1.5.0, NumPy 1.26.4, pandas 2.2.1, OpenCV 4.11.0, Ultralytics 8.4.186, PyTorch 2.14.1 (CPU), React 19, Vite 8"],
               ["`.env` keys", "`BACKEND_PORT` 8310, `FRONTEND_PORT` 5310, `DEMO_EMAIL`, `DEMO_PASSWORD`, `DEMO_NAME`, `JWT_SECRET` (a Gemini key entry in `.env.example` is unused by this product)"],
               ["Hardware used", "Intel Core i5-12500 (6 cores / 12 threads), 15.7 GB RAM, no CUDA GPU; everything runs on the CPU"],
               ["Verification", "`python -m pytest tests` (38 tests); `python scripts/smoke_test.py http://127.0.0.1:8310` (33 checks); `python scripts/measure_api.py`"],
               ["Reproduce the results", "`python scripts/run_experiments.py` (about 2 minutes); `python scripts/fetch_real_images.py` then `python scripts/eval_real_vision.py` (about 1 minute); `python scripts/make_report_facts.py`"]],
              widths=[1.5, 4.9], align=["l", "l"], size=10),
          P("By hand: create a virtual environment, install the two requirements files, run `python -m uvicorn backend.main:app --port 8310` from `8.ProjectCode`, then `npm install` and `npm run dev` inside `frontend/`. "
            "Appendix B gives the full user guide. Measurements in this report were taken against `127.0.0.1` rather than `localhost`, because on the test machine name resolution of `localhost` added about two seconds per client call.")]
    b += [H2("6.11 Reproducibility"),
          P("Every number in this report can be regenerated. `scripts/run_experiments.py` writes one `metrics.json` per experiment under `experiments/`; `scripts/fetch_real_images.py` downloads the two public image sets into the git-ignored `data/external/`; "
            "`scripts/eval_real_vision.py` and `scripts/measure_api.py` write the vision and latency files; `scripts/make_report_facts.py` turns all of them into `docs/REPORT_FACTS.md`, and the documentation build reads the same JSON files, so no result is typed into the text by hand. "
            "All randomness is seeded (demand by the simulation seed, the forecaster's trees by `random_state`), so results are identical on repeated runs; only wall-clock timings vary with machine load.")]
    return b


def _tab_rows(tab, keep_first_col):
    """Return a copy of a TAB block keeping only the rows whose first cell contains one of the given strings."""
    rows = [r for r in tab[3] if any(k in str(r[0]) for k in keep_first_col)]
    return tab[:3] + (rows,) + tab[4:]


