_N_SHORT = ["**Generate demand.** Poisson arrivals at the entry roads of a 2 x 2 or 3 x 3 grid, scaled by a demand slider and a rush-hour profile; a fixed seed makes demand identical for all controllers.",
            "**Sense.** Each approach knows its queue (vehicles and passenger-car units), the vehicles arriving from upstream within 8 s, and whether an ambulance is queued or within 15 s.",
            "**Forecast.** Every 10 s a gradient-boosted model predicts each approach's queue 30 s ahead from eleven features.",
            "**Decide.** Each junction compares the pressure of its green and red phases under minimum and maximum green rules; an ambulance overrides the comparison.",
            "**Discharge and move.** Queued vehicles leave at saturation flow while green, travel the 12 s link or leave the network; a full downstream queue blocks release (spill-back).",
            "**Observe.** The simulator records waiting time, queues, throughput, ambulance delay, violations, fuel and CO2; the vision layer detects vehicles in an image and recommends a green time.",
            "**Compare.** Five seeds per setting, two grid sizes, a demand sweep, an ambulance-heavy test and an ablation, plus vision scoring on synthetic scenes and two public real-photo sets."]


def _trim(bl):
    pr = F.PR["shipped_fit"]["metrics"]
    fmt = dict(rf=pr["Random Forest"]["mae"], gb=pr["Gradient Boosting (used)"]["mae"], pers=pr["Persistence baseline"]["mae"],
               gbm=pr["Gradient Boosting (used)"]["mae"], gbr=pr["Gradient Boosting (used)"]["r2"], pm=pr["Persistence baseline"]["mae"], pr=pr["Persistence baseline"]["r2"],
               a=F.API_PORT, w=F.WEB_PORT,
               bench=f"the first request with four controllers, three seeds and 1,800 s takes about {F.API['results'][-3]['mean_ms'] / 1000:.1f} s and a repeat is served from the cache in about {F.API['results'][-2]['mean_ms']:.0f} ms")
    out, skip_h3 = [], False
    drop_h3 = ("6.5.5 A worked example", "6.5.6 The pressure code")
    for b in bl:
        k = b[0]
        if k == "fig" and (b[1].endswith("02_high_level_workflow.png") or b[1].endswith("01_system_architecture.png")):
            continue
        if k == "h3" and b[1] in drop_h3:
            continue
        if k == "code":
            continue
        if k == "n" and b[1] and b[1][0].startswith("**Generate demand.**"):
            out.append(("n", _N_SHORT))
            continue
        if k == "p":
            hit = next((p for p in _P_RULES if b[1].startswith(p)), None)
            if hit is not None:
                new = _P_RULES[hit]
                if new is not None:
                    out.append(("p", new.format(**fmt)))
                continue
        if k == "tab":
            cap = b[1]
            if cap == "Datasets and their roles.":
                b = _tab_rows(b, ["Simulated demand", "Forecaster training", "Synthetic overhead", "Real mixed", "Real ambulance"])
            elif cap == "Forecaster configuration.":
                b = _tab_rows(b, ["Model", "Baselines", "Training data", "Split"])
            elif cap == "Vision configuration.":
                b = _tab_rows(b, ["Vehicle detector", "Light-bar rule", "Ambulance flag", "Density report"])
            elif cap == "Modules and their responsibilities.":
                continue
            elif cap == "Requirements and settings.":
                b = _tab_rows(b, ["Key packages", ".env", "Hardware", "Verification", "Reproduce"])
        if k == "b" and b[1] and b[1][0].startswith("**Signing key.**"):
            items = [b[1][0], b[1][1], b[1][2] + " Missing components (no ultralytics, a failing YOLO call, a model still training) answer 503, 502 or 500 with a hint.", b[1][5]]
            out.append(("b", items))
            continue
        out.append(b)
    return out


def blocks():
    return [H1("CHAPTER 6: METHODOLOGY AND SOFTWARE IMPLEMENTATION")] + _trim(methodology_blocks() + application_blocks())
